-- verify after 23 (SELECT only): the 3 problems are on E1019-X* versions; the other 4 expression-only problems are unchanged
-- generated by scripts/prod-open/sat-expr-only-fixes-sql.ts. Run: npx supabase db query --linked -f <this file>. Idempotent; new problem_versions only; no deletes/overwrites; set composition untouched.

select p.id as problem_id, pv.version_no, pv.quality->'auditFix'->>'patch' as patch, pv.figure is null as no_figure,
  pv.explanation_en ~ 'adding the flat fee twice' as stale_m012_d, pv.explanation_en ~ 'miscalculating' as stale_m014_5, pv.passage ~ 'sells for \$6\$' as stale_m016_price
from problems p join problem_versions pv on pv.id = p.published_version_id where p.id = any (array['4cc47e7c-e766-47d8-aa9b-ae16aeb96d71','9977438d-6d27-48ed-aebb-c4ad8e08c6c0','f59b7f57-b596-4235-9902-d8036d9040ff']::uuid[]) order by 3;
select count(*) as expr_only_still_figureless from problems p join problem_versions pv on pv.id = p.published_version_id where p.id::text ~ '^(3cdc0ad5|4cc47e7c|e90ca1b1|9977438d|e1f8fcfb|f59b7f57|d1e251f0)' and pv.figure is null;
